function LadderStruggleRankRewardCell:SetPanelInfo(data)
    if isNull(data) then return end
    local noRank = data.noRank
    local name = data.name
    local rewardId = data.reward
    local rewardNum = data.rewardNum

    if isNotNull(noRank) and noRank == 1 then
        KTool.SetActive(self.RT_NoRank, true)
        KTool.SetActive(self.RT_NoReward, true)
        KTool.SetActive(self.Txt_Rank.gameObject, false)
        KTool.SetActive(self.LB_Reward.gameObject, false)
    else
        self.Txt_Rank.text = tostring(name)
        self.LB_Reward.Env:FreshBaseUI({{id = rewardId, num = rewardNum}})
    end
end

